// quantity-choice models: MIT OCW 14.01SC, Oligopoly II and Exam 2 Review (2011).
// Institutional examples are fictional; stale claims about current central-bank mandates are not reused.
const section = (moduleId: string, title: string, lead: string, paragraphs: string[], keyPoints: string[], miniExample?: DeepLesson["sections"][number]["miniExample"]): DeepLesson["sections"][number] => ({ moduleId, title, lead, paragraphs, keyPoints, miniExample });
const formula = (id: string, title: string, latex: string, variables: [string, string, string][], assumptions: string[], domain: string, interpretation: string): DeepLesson["formulas"][number] => ({ id, title, latex, variables: variables.map(([symbol, meaning, unit]) => ({ symbol, meaning, unit })), assumptions, domain, interpretation });
const question = (id: string, objectiveIds: string[], skill: DeepLesson["assessments"][number]["skill"], prompt: string, choices: [string, string][], correctOptionId: "A" | "B" | "C" | "D", solution: string[]): DeepLesson["assessments"][number] => ({ id, objectiveIds, skill, prompt, options: choices.map(([text, feedback], index) => ({ id: (["A", "B", "C", "D"] as const)[index], text, feedback })), correctOptionId, solution });

