      { id: "r17-tariff-welfare", moduleIds: ["17.1"], title: "Account for a tariff's transfers and losses", given: ["A small importing country faces world price 10 and introduces a tariff of 2 per unit.", "Domestic supply rises from 20 to 30 units; demand falls from 80 to 70 units.", "The local supply and demand curves are linear over this price interval."], find: "Imports, tariff revenue, and net national welfare loss.", plan: "Calculate the import gap, then separate transfers from the two distortion triangles.", steps: [{ label: "Trade volumes", result: "Before: imports = 80 - 20 = 60. After: imports = 70 - 30 = 40." }, { label: "Government and distortions", latex: String.raw`R=2(40)=80,\quad DWL=\tfrac12(2)(10)+\tfrac12(2)(10)=20`, result: "Tariff revenue is 80; the production and consumption losses are 10 each." }, { label: "Reconcile welfare", result: "Consumer surplus falls by 2×(80+70)/2 = 150; producer surplus rises by 2×(20+30)/2 = 50. Net national change = -150 + 50 + 80 = -20." }], interpret: "Domestic producers and the government gain, but their gains are smaller than the consumer loss under the small-country assumptions.", sanityCheck: "The net welfare loss equals the sum of the two distortion triangles, and tariff revenue uses post-tariff imports, not the original 60 units." }
